# Hindi and Telugu meanings for every corpus entry, written in plain words
# for app readers. English stays in corpus_data.py. Proofread by a native
# reader before release.

PLANET_NAMES = {
    # planet: (hindi, telugu, telugu dative)
    "Sun": ("सूर्य", "సూర్యుడు", "సూర్యునికి"),
    "Moon": ("चन्द्र", "చంద్రుడు", "చంద్రునికి"),
    "Mars": ("मंगल", "కుజుడు (అంగారకుడు)", "కుజునికి"),
    "Mercury": ("बुध", "బుధుడు", "బుధునికి"),
    "Jupiter": ("गुरु (बृहस्पति)", "గురువు (బృహస్పతి)", "గురువుకు"),
    "Venus": ("शुक्र", "శుక్రుడు", "శుక్రునికి"),
    "Saturn": ("शनि", "శని", "శనికి"),
    "Rahu": ("राहु", "రాహువు", "రాహువుకు"),
    "Ketu": ("केतु", "కేతువు", "కేతువుకు"),
}


def bija(planet):
    hi, te, te_dat = PLANET_NAMES[planet]
    return (f"ॐ, {hi} के बीज अक्षर, {hi} को नमस्कार। बीज अक्षरों का कोई शब्दकोशीय अर्थ नहीं होता।",
            f"ఓం, {te} బీజాక్షరాలు, {te_dat} నమస్కారం. బీజాక్షరాలకు నిఘంటు అర్థం ఉండదు.")


